1. private LockResultVO tryAcquire(String key, final String value, Long expireMilliseconds, Integer retryTimes) {
2.         Preconditions.checkArgument(StringUtils.isNotBlank(key), "lock key is null");
3.         Preconditions.checkArgument(StringUtils.isNotBlank(value), "value is null");
4.         checkRange(expireMilliseconds, 1L, 60000L);
5.         checkRange(retryTimes, 0, 30);
6. 
7.         long ttlInMilliseconds = expireMilliseconds != null ? expireMilliseconds : DEFAULT_TTL_IN_MILLISECONDS;
8.         int count = retryTimes != null ? retryTimes : DEFAULT_RETRY_TIMES;
9. 
10.         String lockKey = addPrefix(key);
11. 
12.         do {
13.             long timestamp = System.currentTimeMillis();
14. 
15.             Long result = redisTemplate.execute(ACQUIRE_REDIS_LOCK_SCRIPT,
16.                     Collections.singletonList(lockKey),// KEYS[1]
17.                     value, // ARGV[1]
18.                     String.valueOf(ttlInMilliseconds) // ARGV[2]
19.             );
20. 
21.             if (SUCCESS.equals(result)) {
22.                 return LockResultVO.newInstance(true, key, value, new Date(timestamp + ttlInMilliseconds));
23.             }
24. 
25.             count--;
26. 
27.             if (count > 0) {
28.                 Uninterruptibles.sleepUninterruptibly(DEFAULT_INTERVAL_IN_MILLISECONDS, TimeUnit.MILLISECONDS);
29.             }
30.         } while (count > 0);
31. 
32.         return LockResultVO.newInstance(false, key, null, null);
