private boolean newInstanceScript(GroovyClassLoader loader, GatewayScript script) {
        Optional<ScriptEnum> type = ScriptEnum.get(script.getType());
        if (!type.isPresent()) {
            log.error("实例化脚本【失败】:scriptId【{}】,title【{}】,脚本类型【{}】", script.getScriptId(), script.getTitle(), script.getType());
            return false;
        }

        try {
            Class<?> c = loader.parseClass(script.getContent());
            GroovyObject groovy = (GroovyObject) c.newInstance();
            switch (type.get()) {
                case GATEWAY_CONTENT:
                    scriptClass.put(script.getScriptId(), new GatewayContentScriptProxy(groovy));
                    break;
                case EXTERNAL_RESULT:
                    scriptClass.put(script.getScriptId(), new ExternalServiceResultScriptProxy(groovy));
                    break;
                default:
                    log.error("实例化脚本【失败】:scriptId【{}】,title【{}】,不支持的脚本类型【{}】", script.getScriptId(), script.getTitle(), script.getType());
                    return false;
            }

            log.info("实例化脚本【成功】:scriptId【{}】,title【{}】", script.getScriptId(), script.getTitle());
            return true;
        } catch (Exception e) {
            log.error("实例化脚本【异常】:scriptId【{}】,title【{}】", script.getScriptId(), script.getTitle(), e);
        }
        return false;
    }

@Override
    public LockResultVO lock(LockKeyVO lockKeyVO) {
        String value = String.valueOf(System.currentTimeMillis());
        try {
            return this.tryAcquire(lockKeyVO.getKey(), value, DEFAULT_TTL_IN_MILLISECONDS, 1);
        } catch (Exception e) {
            log.error("redis, key:{}, retry:{}, expire:{} 加锁异常", lockKeyVO.getKey(), lockKeyVO.getRetryCount(), lockKeyVO.getExpireMilliseconds(), e);
        }
        return LockResultVO.newInstance(false, lockKeyVO.getKey(), null, null);
    }

private LockResultVO tryAcquire(String key, final String value, Long expireMilliseconds, Integer retryTimes) {
        Preconditions.checkArgument(StringUtils.isNotBlank(key), "lock key is null");
        Preconditions.checkArgument(StringUtils.isNotBlank(value), "value is null");
        checkRange(expireMilliseconds, 1L, 60000L);
        checkRange(retryTimes, 0, 30);

        long ttlInMilliseconds = expireMilliseconds != null ? expireMilliseconds : DEFAULT_TTL_IN_MILLISECONDS;
        int count = retryTimes != null ? retryTimes : DEFAULT_RETRY_TIMES;

        String lockKey = addPrefix(key);

        do {
            long timestamp = System.currentTimeMillis();

            Long result = redisTemplate.execute(ACQUIRE_REDIS_LOCK_SCRIPT,
                    Collections.singletonList(lockKey),// KEYS[1]
                    value, // ARGV[1]
                    String.valueOf(ttlInMilliseconds) // ARGV[2]
            );

            if (SUCCESS.equals(result)) {
                return LockResultVO.newInstance(true, key, value, new Date(timestamp + ttlInMilliseconds));
            }

            count--;

            if (count > 0) {
                Uninterruptibles.sleepUninterruptibly(DEFAULT_INTERVAL_IN_MILLISECONDS, TimeUnit.MILLISECONDS);
            }
        } while (count > 0);

        return LockResultVO.newInstance(false, key, null, null);
    }

